struct SegTree {
    int n;
    vector<long long> st;
    SegTree(int _n = 0) { init(_n); }
    void init(int _n) {
        n = 1;
        while (n < _n) n <<= 1;
        st.assign(2 * n, LLONG_MIN);
    }

    void point_update_max(int p, long long val) {
        p = p - 1 + n; 
        if (st[p] >= val) return;
        st[p] = val;
        for (p >>= 1; p; p >>= 1) {
            st[p] = max(st[p << 1], st[(p << 1) | 1]);
        }
    }

    long long range_max(int l, int r) {
        if (l > r) return LLONG_MIN;
        int L = l - 1 + n;
        int R = r - 1 + n;
        long long res = LLONG_MIN;
        while (L <= R) {
            if (L & 1) res = max(res, st[L++]);
            if (!(R & 1)) res = max(res, st[R--]);
            L >>= 1; R >>= 1;
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<long long> h(n + 1);
    vector<int> a(n + 1), b(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> h[i] >> a[i] >> b[i];
    }
    int q;
    cin >> q;
    vector<pair<int,int>> queries(q);
    for (int i = 0; i < q; ++i) {
        cin >> queries[i].first >> queries[i].second;
    }

    vector<vector<pair<int,int>>> by_r(n + 1);
    for (int i = 0; i < q; ++i) {
        int l = queries[i].first;
        int r = queries[i].second;
        by_r[r].push_back({l, i});
    }
    vector<long long> ans(q, -1);

    SegTree seg(n);

    for (int r = 1; r <= n; ++r) {

        for (int i = 1; i < r; ++i) {
            int d = r - i;

            if (a[i] <= d && d <= b[i] && a[r] <= d && d <= b[r]) {
                long long diff = llabs(h[i] - h[r]);

                seg.point_update_max(i, diff);
            }
        }

        for (auto &pr : by_r[r]) {
            int l = pr.first;
            int qi = pr.second;
            if (l >= r) {

                ans[qi] = -1;
            } else {
                long long res = seg.range_max(l, r - 1);
                if (res == LLONG_MIN) ans[qi] = -1;
                else ans[qi] = res;
            }
        }
    }

    for (int i = 0; i < q; ++i) {
        cout << ans[i] << '\n';
    }
}